        },
        {
          "source_id": "P019",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        },
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans specify the measurements, classification safeguards, interval reduction and association-only limit."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C040.stated_empirical_relation",
    "value": "Matched retesting reproduces the regression across the localized boundary, and testing a targeted revert or fix while holding other factors constant reproduces its reversal.",
    "scope": "Confirmation under tested conditions licenses the compatible intervention's bounded overnight canary, with predefined tail-rate, failure and resource stop thresholds. Expansion requires adequate further evidence; otherwise the canary is halted or rolled back.",
    "provenance": {
      "refs": [
        {
          "source_id": "P025",
          "role": "SUPPORT"
        },
        {
          "source_id": "P026",
          "role": "SUPPORT"
        },
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P025 specifies the controlled confirmation tests; P026 explicitly connects reproduced regression and reversal to the bounded canary recommendation. P034 preserves the need for monitored rollout."
    }
  },
  "rationale": "The localization signal alone establishes a revision association. The mapping supplies a specific additional empirical relation—reproduction of the regression and its reversal under controlled comparison—that would warrant the claimed bounded deployment experiment. This is an inferential confirmation condition, not merely an execution prerequisite.",
  "uncertainty": "The packet does not establish that the regression and reversal reproduce. Even if they do, the recommendation remains limited to a compatible, monitored canary and does not establish general deployment safety.",
  "anomalies": []
}
